#!/usr/bin/env bash
# Prints the Homebrew formula for a release.
# Usage: homebrew-formula.sh VERSION MACOS_SHA256 LINUX_SHA256
set -euo pipefail

version="$1"
macos_sha="$2"
linux_sha="$3"
base="https://github.com/vangheem/kargoslop/releases/download/v${version}"

cat <<FORMULA
# Generated by vangheem/kargoslop's release workflow; edits here are overwritten.
class Kargoslop < Formula
  desc "Native desktop view of Kargo pipelines, Argo CD apps and their Kubernetes resources"
  homepage "https://github.com/vangheem/kargoslop"
  version "${version}"
  license "MIT"

  on_macos do
    url "${base}/kargoslop-macos-universal.tar.gz"
    sha256 "${macos_sha}"
  end

  on_linux do
    on_intel do
      url "${base}/kargoslop-linux-x86_64.tar.gz"
      sha256 "${linux_sha}"
    end
  end

  def install
    bin.install "kargoslop"
  end

  def caveats
    <<~EOS
      kargoslop drives the kargo, argocd and kubectl CLIs, logged in as you:
        kargo login https://kargo.example.com --sso
        argocd login argocd.example.com --sso --grpc-web
      kubectl needs a context for each cluster Argo CD deploys to.

      On macOS, add kargoslop to ~/Applications (Spotlight, Launchpad, Dock) with:
        kargoslop install-app
      kargoslop also offers to do this the first time you run it.
    EOS
  end

  test do
    assert_match "demo", shell_output("#{bin}/kargoslop --list-scenes")
  end
end
FORMULA
